/* A hymn page (generated by tools/blog/build.mjs): draws the staff with the same pinned engraver
 * the web app uses, once it scrolls into view, and plays the melody on the NfChoir piano with the
 * sounding note lit in the solfa grid. The solfa and words are plain HTML and need none of this.
 * Plain script, no build step; needs assets/choir.js loaded first for the player. */
(function () {
  "use strict";
  var dataEl = document.getElementById("hymn-data");
  if (!dataEl) return;
  var data;
  try { data = JSON.parse(dataEl.textContent); } catch (e) { return; }

  // ── Staff ───────────────────────────────────────────────────────────────
  var staff = document.getElementById("staff");
  function loadOsmd() {
    if (window.opensheetmusicdisplay) return Promise.resolve();
    return new Promise(function (res, rej) {
      var s = document.createElement("script");
      s.src = data.osmd.url; s.integrity = data.osmd.sri; s.crossOrigin = "anonymous";
      s.onload = res; s.onerror = rej; document.head.appendChild(s);
    }).then(function () { if (!window.opensheetmusicdisplay) throw new Error("engraver"); });
  }
  var engraved = false;
  /** Smaller notes on a narrow box, so a phone gets a few bars to a line instead of one. */
  function zoomFor(width) { return width < 380 ? 0.5 : width < 460 ? 0.55 : width < 600 ? 0.7 : width < 760 ? 0.85 : 1; }
  function engrave() {
    if (engraved || !staff) return;
    engraved = true;
    staff.innerHTML = '<p class="staff-wait">Drawing the staff…</p>';
    loadOsmd().then(function () {
      staff.innerHTML = "";
      var d = new window.opensheetmusicdisplay.OpenSheetMusicDisplay(staff, {
        backend: "svg", autoResize: false, drawTitle: false, drawSubtitle: false, drawComposer: false,
        drawLyricist: false, drawPartNames: false, drawMeasureNumbers: true, autoBeam: true
      });
      return d.load(data.musicXml).then(function () {
        var width = staff.clientWidth;
        d.zoom = zoomFor(width);
        d.render();
        // Re-drawn for the new width after a resize or a turn of the phone, once it settles.
        var timer = null;
        window.addEventListener("resize", function () {
          clearTimeout(timer);
          timer = setTimeout(function () {
            if (staff.clientWidth === width) return;
            width = staff.clientWidth;
            d.zoom = zoomFor(width);
            try { d.render(); } catch (e) { /* keep the last drawing */ }
          }, 200);
        });
      });
    }).catch(function () {
      staff.innerHTML = '<p class="staff-wait">The staff could not be drawn right now. The solfa above has every note.</p>';
    });
  }
  if (staff) {
    if ("IntersectionObserver" in window) {
      var io = new IntersectionObserver(function (entries) {
        if (entries.some(function (e) { return e.isIntersecting; })) { io.disconnect(); engrave(); }
      }, { rootMargin: "300px 0px" });
      io.observe(staff);
    } else engrave();
  }

  // ── Player ──────────────────────────────────────────────────────────────
  var C = window.NfChoir, box = document.getElementById("player"), btn = document.getElementById("play"), rate = document.getElementById("rate");
  if (!C || !box || !btn || !(window.AudioContext || window.webkitAudioContext)) return;
  box.hidden = false;
  var cells = Array.prototype.map.call(document.querySelectorAll("#hymn-grid [data-beat]"), function (el) {
    return { el: el, beat: parseFloat(el.getAttribute("data-beat")) };
  });
  var player = null, lit = null;
  function light(beat, playing) {
    var now = null;
    for (var i = 0; i < cells.length; i++) if (cells[i].beat <= beat + 1e-6 && cells[i].el.textContent !== "-" && cells[i].el.textContent !== "_") now = cells[i].el;
    if (!playing) now = null;
    if (now === lit) return;
    if (lit) lit.classList.remove("now");
    if (now) now.classList.add("now");
    lit = now;
  }
  // The bar at the foot of a phone's screen (board n-ux-low V3e): once the tune has started and the player above is
  // scrolled away, it keeps Play/Pause and the speed in reach; it goes when the player is back in view or the tune
  // ends (the player's last tick: stopped, back at beat 0). CSS shows it on phones only.
  var mini = document.getElementById("mini-player"), miniBtn = document.getElementById("mini-play"), miniRate = document.getElementById("mini-rate");
  var started = false, boxInView = true, miniOn = false;
  function updateMini() {
    var on = !!mini && started && !boxInView;
    if (on === miniOn) return;
    miniOn = on;
    mini.hidden = !on;
    document.body.classList.toggle("has-mini-player", on);
  }
  if (mini && "IntersectionObserver" in window) {
    // Under the sticky header counts as out of view.
    new IntersectionObserver(function (entries) {
      boxInView = entries[entries.length - 1].isIntersecting;
      updateMini();
    }, { rootMargin: "-64px 0px 0px 0px" }).observe(box);
  }
  function label(text) { btn.textContent = text; if (miniBtn) miniBtn.textContent = text; }
  function toggle() {
    // The audio context is made on the first press, inside the gesture, so the browser lets it play.
    if (!player) {
      player = C.createPlayer();
      player.load({ voices: [{ name: "melody", notes: data.notes, gain: 1 }], tempoBpm: data.tempo, timeSignature: data.time });
      player.onTick(function (t) {
        label(t.playing ? "Pause" : "Play");
        light(t.beat, t.playing);
        if (t.playing) started = true; else if (t.beat === 0) started = false;
        updateMini();
      });
      if (rate) player.setRate(parseFloat(rate.value) || 1);
      if (window.nfTrack) window.nfTrack("Hymn played", location.pathname);
    }
    if (!player.isPlaying()) label("Loading…");
    player.toggle();
  }
  btn.addEventListener("click", toggle);
  if (miniBtn) miniBtn.addEventListener("click", toggle);
  /** Either speed control sets the one player's rate, and the other follows. */
  function speed(from, to) {
    if (to) to.value = from.value;
    if (player) player.setRate(parseFloat(from.value) || 1);
  }
  if (rate) rate.addEventListener("change", function () { speed(rate, miniRate); });
  if (miniRate) miniRate.addEventListener("change", function () { speed(miniRate, rate); });
})();
